    [5967]={name="Girdle of Nobility",quality=2,ilvl=20,reqLevel=15,sourceType="rare_npc",instructions="Drops from Brainwashed Noble.",zone="The Deadmines",npc="Brainwashed Noble"},
    [5969]={name="Regent's Cloak",quality=2,ilvl=24,reqLevel=19,sourceType="rare_npc",instructions="Drops from Ravenclaw Regent.",zone="Silverpine Forest",npc="Ravenclaw Regent"},
    [5970]={name="Serpent Gloves",quality=3,ilvl=23,reqLevel=18,sourceType="boss_drop",instructions="Drops from Lord Serpentis.",zone="Wailing Caverns",npc="Lord Serpentis"},
    [5971]={name="Feathered Cape",quality=2,ilvl=28,reqLevel=23,sourceType="rare_npc",instructions="Drops from Vultros.",zone="Westfall",npc="Vultros"},
    [5975]={name="Ruffian Belt",quality=2,ilvl=24,reqLevel=19,sourceType="rare_npc",instructions="Drops from Rot Hide Bruiser.",zone="Alterac Mountains",npc="Rot Hide Bruiser"},
    [6058]={name="Blackened Leather Belt",quality=1,ilvl=5,reqLevel=1,sourceType="quest_reward",instructions="Reward from the quest 'The Balance of Nature'. Pick it over the other reward choices. Starts with Conservator Ilthalaine in Teldrassil. Objective: Kill 7 Young Nightsabers and 4 Young Thistle Boars and return to Conservator Ilthalaine.",zone="Teldrassil",questName="The Balance of Nature",lore="Thinning the younger population of creatures here in Shadowglen was a good start, but there is still work to be done. The resources of the forest will be depleted too quickly if the problem is not addressed."},
    [6085]={name="Footman Tunic",quality=2,ilvl=13,reqLevel=5,sourceType="quest_reward",instructions="Reward from the quest 'Wanted: \"Hogger\"'. Pick it over the other reward choices.",zone="Elwynn Forest",questName="Wanted:  \"Hogger\"",lore="Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn. He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."},
    [6092]={name="Black Whelp Boots",quality=2,ilvl=18,reqLevel=14,sourceType="quest_reward",instructions="Reward from the quest 'Underbelly Scales'. Pick it over the other reward choices. Starts with Verner Osgood in Redridge Mountains. Objective: Gather 6 Underbelly Whelp Scales from Black Dragon Whelps, and bring them to Verner Osgood in Redridge.",zone="Redridge Mountains",questName="Underbelly Scales",lore="I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire."},
    [6093]={name="Orc Crusher",quality=2,ilvl=27,reqLevel=18,sourceType="quest_reward",instructions="Reward from the quest 'Tharil'zun'. Pick it over the other reward choices.",zone="Redridge Mountains",questName="Tharil'zun",lore="Blackrock Outrunners and Renegades are running ambushes between here and Stonewatch Keep. The leader of the Outrunners is an orc named Tharil'zun--we want this orc."},
    [6095]={name="Wandering Boots",quality=2,ilvl=24,reqLevel=20,sourceType="quest_reward",instructions="Reward from the quest 'Return to Kristoff'. Starts with Brother Paxton in Stormwind City. Objective: Return to Brother Kristoff in the Cathedral Square. Give him the book The Stresses of Iron.",zone="Stormwind City",questName="Return to Kristoff",lore="Now that I've finished copying the book, here's the original Stresses of Iron. Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay."},
    [6147]={name="Ratty Old Belt",quality=2,ilvl=12,reqLevel=7,sourceType="rare_npc",instructions="Drops from Narg the Taskmaster.",zone="Elwynn Forest",npc="Narg the Taskmaster"},
