    [11962]={name="Manacle Cuffs",quality=3,ilvl=55,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'The Love Potion'. Pick it over the other reward choices.",zone="Blackrock Depths",questName="The Love Potion",lore="Oh, the pains of love! My dear Private Rocknot is immune to my charms. I am spurned! It's maddening! You must help me! We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot's heart."},
    [11963]={name="Penance Spaulders",quality=2,ilvl=53,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Ribbly Screwspigot'. Pick it over the other reward choices. Starts with Yuka Screwspigot in Burning Steppes. Objective: Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.",zone="Blackrock Depths",questName="Ribbly Screwspigot",lore="My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another."},
